public DimensionDynamicAccount ledgerDimension()
{
    DimensionDynamicAccount ret = next ledgerDimension();

    if (!FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        return ret;
    }

    if (this.Recipient)
    {
        ret = LedgerDynamicAccountHelper::getDynamicAccountFromAccountNumber(this.Recipient, LedgerJournalACType::Cust);
    }

    return ret;
}
